/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void reset_long_register (Reset_Func reset_long_func)
{
  CRITICAL ;

  C_ENTER ;
    {
      add_to_list :
        {
          Reset_Entry * reset_long_entry = (Reset_Entry *) os_mem_request (sizeof (Reset_Entry)) ;
    
          reset_long_entry -> reset_func = reset_long_func ;
          reset_long_entry -> next       = reset_long_list ;
    
          reset_long_list = reset_long_entry ;
        }
    }
  C_LEAVE ;
}


